// Generated by vuetify-ext create dialog form
import { $DF, $FD, $FM, $PT, type ReportMode } from 'vuetify-extended';

export function createQuickEditDialogForm(mode: ReportMode = "create") {
  return $DF(
    {
      ref: "quick-edit",
      closeOnSave: true,
      mode,
    },
    {
      form: async () =>
        $FM(
          {
            title: { key: "dialogs.quick-edit.title", fallback: "Quick Edit" },
            mode,
            width: 760,
          },
          {
            children: () => [
              $PT(
                { cols: 12, dense: true },
                {
                  children: () => [
                    $FD({
                      label: { key: "dialogs.quick-edit.fields.title.label", fallback: "Title" },
                      storage: 'title',
                      cols: 6,
                      required: true,
                    }),
                    $FD({
                      label: { key: "dialogs.quick-edit.fields.owner.label", fallback: "Owner" },
                      storage: 'owner',
                      cols: 6,
                    }),
                    $FD({
                      label: { key: "dialogs.quick-edit.fields.summary.label", fallback: "Summary" },
                      storage: 'summary',
                      type: 'textarea',
                      cols: 12,
                    }),
                  ],
                },
              ),
            ],
          },
        ),
    },
  );
}
